import 'package:flutter/material.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> {
  late Future<List<dynamic>> _dashboardFuture;

  @override
  void initState() {
    super.initState();
    _initData();
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait<dynamic>([
      currencyRepository.fetchRates(const CurrencyPageRequest(base: 'USD')).then((CurrencyPage page) => page.items),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboardTitle)),
      body: FutureBuilder<List<dynamic>>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<List<dynamic>> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting) {
            return const _DashboardProgressIndicator();
          }

          if (!snapshot.hasData || snapshot.data!.length < 2) {
            return const Center(child: Text('Error loading data'));
          }

          final List<CurrencyModel> currencies = snapshot.data![0] as List<CurrencyModel>;
          final List<NewsModel> news = snapshot.data![1] as List<NewsModel>;

          return SingleChildScrollView(
            child: Padding(
              padding: const EdgeInsets.all(16),
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Text(
                    context.loc.currencyRate,
                    style: context.fonts.semiBold16,
                  ),
                  const SizedBox(height: 8),
                  GridView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      childAspectRatio: 3.5,
                      crossAxisSpacing: 8,
                      mainAxisSpacing: 8,
                    ),
                    itemCount: currencies.length,
                    itemBuilder: (BuildContext context, int index) {
                      return CurrencyCard(model: currencies[index]);
                    },
                  ),
                  const SizedBox(height: 16),
                  Text(
                    context.loc.newsSection,
                    style: context.fonts.semiBold16,
