{"content":"import 'dart:async';

import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/app/currency_list/widgets/currency_card.dart';
import 'package:mad_flutter_practicum/app/news_list/widgets/news_card.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    late List<CurrencyModel> currencyItems;
    late List<NewsModel> newsItems;

    setUp(() {
      currencyItems = [
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Доллар США',
          symbol: 'USD',
          value: 78.42,
          previousValue: 78.50,
        ),
      ];

      newsItems = [
        NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
        NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
      ];

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: currencyItems, page: 0, hasMore: false));
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsItems);
    });

    Widget buildDashboardWidget() {
      return buildWidget(
        providers: [
          Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
          Provider<NewsRepository>.value(value: mockNewsRepository),
        ],
        child: const DashboardPage(),
      );
    }

    testWidgets('should display progress indicator while loading', (WidgetTester tester) async {
      final Completer<CurrencyPage> currencyCompleter = Completer<CurrencyPage>();
      final Completer<List<NewsModel>> newsCompleter = Completer<List<NewsModel>>();

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) => currencyCompleter.future);
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) => newsCompleter.future);

      await tester.pumpWidget(buildDashboardWidget());

      expect(find.byType(LinearProgressIndicator), findsOneWidget);
    });

    testWidgets('should display currency cards and news after loading', (WidgetTester tester) async {
      await tester.pumpWidget(buildDashboardWidget());
      await tester.pumpAndSettle();

      // Проверяем наличие заголовка дашборда
      expect(find.text('Дашборд'), findsOneWidget);

      // Проверяем наличие валютных карточек
      expect(find.byType(CurrencyCard), findsOneWidget);
      expect(find.text('Доллар США'), findsOneWidget);
      expect(find.text('78.42'), findsOneWidget);

      // Проверяем наличие новостей
      expect(find.byType(NewsCard), findsNWidgets(2));
      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
    });

    testWidgets('should show error state when loading fails', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenThrow(Exception('Network error'));
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsItems);

      await tester.pumpWidget(buildDashboardWidget());
      await tester.pumpAndSettle();

      expect(find.textContaining('Error'), findsOneWidget);
    });

    testWidgets('should show error state with empty currency list', (WidgetTester tester) async {
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => CurrencyPage(items: [], page: 0, hasMore: false));

      await tester.pumpWidget(buildDashboardWidget());
      await tester.pumpAndSettle();

      expect(find.textContaining('Error'), findsOneWidget);
    });
  });
}
